import{_ as d,o as a,c as e,ag as o}from"./chunks/framework.CrXGS008.js";const y=JSON.parse('{"title":"Ustawienia","description":"","frontmatter":{},"headers":[],"relativePath":"pl/repair-station/settings.md","filePath":"pl/repair-station/settings.md"}'),i={name:"pl/repair-station/settings.md"};function n(r,t,c,s,l,h){return a(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="ustawienia" tabindex="-1">Ustawienia <a class="header-anchor" href="#ustawienia" aria-label="Permalink to &quot;Ustawienia&quot;">​</a></h1><p>Każde ustawienie Repair Station edytuje się w <code>/nay</code>, na stronie <strong>Repair Station</strong> (scope <code>nay_repair.config</code>). Zmiany zapisują się w bazie danych i działają od razu dla wszystkich graczy. <code>config.lua</code> zawiera opcjonalne wartości startowe: obowiązują, dopóki ustawienie nie zostanie zmienione w <code>/nay</code>, a <strong>Resetuj</strong> do nich wraca.</p><p>Kolumna <strong>W /nay</strong> to nazwa wyświetlana w panelu. Klucz to nazwa używana przez <code>config.lua</code> i <a href="/pl/nay-lib/api">API HTTP</a>.</p><h2 id="ogolne" tabindex="-1">Ogólne <a class="header-anchor" href="#ogolne" aria-label="Permalink to &quot;Ogólne&quot;">​</a></h2><table tabindex="0"><thead><tr><th>W /nay</th><th>Klucz</th><th>Typ</th><th>Domyślnie</th><th>Opis</th></tr></thead><tbody><tr><td>Włączone</td><td><code>Enabled</code></td><td>wł. / wył.</td><td>wł.</td><td>Włącza lub wyłącza wszystkie stacje.</td></tr><tr><td>Konto płatności</td><td><code>Account</code></td><td><code>cash</code>, <code>bank</code> lub <code>cash_then_bank</code></td><td><code>cash_then_bank</code></td><td>Skąd pobierana jest opłata. <code>cash_then_bank</code> korzysta z banku, gdy brakuje gotówki.</td></tr><tr><td>Zniżki dla zawodów</td><td><code>JobDiscounts</code></td><td>lista, do 32</td><td>brak</td><td>Zniżki dla zawodu od określonej rangi.</td></tr><tr><td>Czas oczekiwania (sekundy)</td><td><code>CooldownSeconds</code></td><td>sekundy, 0 do 3600</td><td>0</td><td>Minimalny czas między dwiema naprawami tego samego gracza. 0 wyłącza.</td></tr></tbody></table><p>Wpisy <strong>Zniżki dla zawodów</strong>:</p><table tabindex="0"><thead><tr><th>W /nay</th><th>Klucz</th><th>Typ</th><th>Opis</th></tr></thead><tbody><tr><td>Zawód</td><td><code>Job</code></td><td>tekst, 1 do 32 znaków</td><td>Nazwa zawodu, taka jak w Twoim frameworku.</td></tr><tr><td>Minimalna ranga</td><td><code>MinGrade</code></td><td>liczba, 0 do 100</td><td>Najniższa ranga, która otrzymuje zniżkę.</td></tr><tr><td>Zniżka (%)</td><td><code>Percent</code></td><td>liczba, 1 do 100</td><td>Zniżka w procentach. 100 oznacza darmową naprawę.</td></tr></tbody></table><h2 id="usługi" tabindex="-1">Usługi <a class="header-anchor" href="#usługi" aria-label="Permalink to &quot;Usługi&quot;">​</a></h2><table tabindex="0"><thead><tr><th>W /nay</th><th>Klucz</th><th>Typ</th><th>Domyślnie</th><th>Opis</th></tr></thead><tbody><tr><td>Usługi naprawy</td><td><code>Services</code></td><td>lista, 1 do 8</td><td>Quick fix 250 $, Body work 400 $, Full repair 700 $</td><td>Usługi oferowane w każdej stacji.</td></tr><tr><td>Cena zależna od uszkodzeń</td><td><code>PriceByDamage</code></td><td>wł. / wył.</td><td>wł.</td><td>Zmienia cenę zależnie od uszkodzeń naprawianych części.</td></tr><tr><td>Cena minimalna (%)</td><td><code>MinPricePercent</code></td><td>liczba, 0 do 100</td><td>20</td><td>Najniższy udział ceny usługi, gdy cena zależy od uszkodzeń.</td></tr><tr><td>Odrzucaj nieuszkodzone pojazdy</td><td><code>RequireDamage</code></td><td>wł. / wył.</td><td>wł.</td><td>Odrzuca usługę, gdy naprawiane przez nią części są sprawne.</td></tr><tr><td>Zablokowane klasy pojazdów</td><td><code>BlockedClasses</code></td><td>lista klas pojazdów</td><td>rowery, łodzie, helikoptery, samoloty, pociągi</td><td>Klasy pojazdów odrzucane na stacji.</td></tr></tbody></table><p>Wpisy <strong>Usługi naprawy</strong>:</p><table tabindex="0"><thead><tr><th>W /nay</th><th>Klucz</th><th>Typ</th><th>Opis</th></tr></thead><tbody><tr><td>Nazwa</td><td><code>Label</code></td><td>tekst, 1 do 32 znaków</td><td>Nazwa wyświetlana w menu napraw, historii i webhookach.</td></tr><tr><td>Cena</td><td><code>Price</code></td><td>liczba, 0 do 1000000</td><td>Cena przy pełnych uszkodzeniach, przed zniżkami i procentem stacji.</td></tr><tr><td>Czas trwania (sekundy)</td><td><code>Seconds</code></td><td>liczba, 3 do 120</td><td>Jak długo trwa naprawa.</td></tr><tr><td>Naprawia silnik</td><td><code>Engine</code></td><td>wł. / wył.</td><td>Obejmuje zbiornik paliwa.</td></tr><tr><td>Naprawia karoserię</td><td><code>Body</code></td><td>wł. / wył.</td><td>Obejmuje szyby, drzwi i deformacje.</td></tr><tr><td>Naprawia opony</td><td><code>Tyres</code></td><td>wł. / wył.</td><td>Naprawia wszystkie przebite opony.</td></tr></tbody></table><p>Gdy <code>PriceByDamage</code> jest włączone, cena to cena usługi pomnożona przez największe uszkodzenie naprawianych części, nigdy poniżej <code>MinPricePercent</code> ani powyżej 100 procent. Potem stosowane są procent stacji i zniżka dla zawodu. Po wyłączeniu zawsze pobierana jest pełna cena.</p><p>Wpisy <strong>Zablokowane klasy pojazdów</strong> mają jedno pole, <strong>Klasa</strong> (<code>Class</code>), wybierane według nazwy spośród klas pojazdów GTA.</p><h2 id="stations" tabindex="-1">Stacje <a class="header-anchor" href="#stations" aria-label="Permalink to &quot;Stacje {#stations}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>W /nay</th><th>Klucz</th><th>Typ</th><th>Domyślnie</th><th>Opis</th></tr></thead><tbody><tr><td>Stacje</td><td><code>Stations</code></td><td>lista, do 64</td><td>Hayes Autos, Sandy Shores, Paleto Bay</td><td>Stacje. Ustawiane w <a href="/pl/repair-station/stations">edytorze stacji</a>.</td></tr></tbody></table><p>Wpisy łatwiej edytować w <a href="/pl/repair-station/stations">edytorze stacji</a>, który wypełnia te pola za Ciebie:</p><table tabindex="0"><thead><tr><th>W /nay</th><th>Klucz</th><th>Typ</th><th>Opis</th></tr></thead><tbody><tr><td>Identyfikator</td><td><code>Id</code></td><td>tekst, 8</td><td>8 znaków (od 0 do 9, od a do f), nadawane przez edytor. Musi być unikalny.</td></tr><tr><td>Nazwa</td><td><code>Label</code></td><td>tekst, do 48 znaków</td><td>Wyświetlana w podpowiedzi, historii i webhookach. Opcjonalne.</td></tr><tr><td>Otwarta</td><td><code>Enabled</code></td><td>wł. / wył.</td><td>Zamyka jedną stację bez usuwania jej.</td></tr><tr><td>Pozycja pojazdu</td><td><code>Coords</code></td><td>pozycja i kierunek</td><td>Miejsce zatrzymania pojazdów, z kierunkiem.</td></tr><tr><td>Promień (m)</td><td><code>Radius</code></td><td>metry, 1,5 do 6</td><td>Maksymalna odległość od pozycji, w której pojazd jest jeszcze na stacji.</td></tr><tr><td>Cena (%)</td><td><code>PricePercent</code></td><td>liczba, 0 do 1000</td><td>Procent stosowany do każdej ceny w tej stacji. 100 zachowuje ceny.</td></tr><tr><td>Model propa</td><td><code>Prop</code></td><td>tekst, do 64 znaków</td><td>Prop postawiony obok stacji. Opcjonalne.</td></tr><tr><td>Pozycja propa</td><td><code>PropCoords</code></td><td>pozycja i kierunek</td><td>Miejsce propa. Opcjonalne.</td></tr><tr><td>Blip na mapie</td><td><code>Blip</code></td><td>wł. / wył.</td><td>Pokazuje tę stację na mapie.</td></tr></tbody></table><h2 id="mechanicy" tabindex="-1">Mechanicy <a class="header-anchor" href="#mechanicy" aria-label="Permalink to &quot;Mechanicy&quot;">​</a></h2><table tabindex="0"><thead><tr><th>W /nay</th><th>Klucz</th><th>Typ</th><th>Domyślnie</th><th>Opis</th></tr></thead><tbody><tr><td>Zawody mechaników</td><td><code>MechanicJobs</code></td><td>lista, do 16</td><td><code>mechanic</code></td><td>Zawody liczone jako mechanicy na służbie.</td></tr><tr><td>Limit mechaników na służbie</td><td><code>MaxMechanicsOnDuty</code></td><td>liczba, 0 do 64</td><td>0</td><td>Stacje są zamknięte, gdy na służbie jest tylu mechaników lub więcej. 0 nigdy ich nie zamyka.</td></tr></tbody></table><p>Wpisy <strong>Zawody mechaników</strong>:</p><table tabindex="0"><thead><tr><th>W /nay</th><th>Klucz</th><th>Typ</th><th>Opis</th></tr></thead><tbody><tr><td>Zawód</td><td><code>Job</code></td><td>tekst, 1 do 32 znaków</td><td>Nazwa zawodu, taka jak w Twoim frameworku.</td></tr></tbody></table><h2 id="blipy" tabindex="-1">Blipy <a class="header-anchor" href="#blipy" aria-label="Permalink to &quot;Blipy&quot;">​</a></h2><table tabindex="0"><thead><tr><th>W /nay</th><th>Klucz</th><th>Typ</th><th>Domyślnie</th><th>Opis</th></tr></thead><tbody><tr><td>Pokaż blipy</td><td><code>ShowBlips</code></td><td>wł. / wył.</td><td>wł.</td><td>Pokazuje na mapie stacje, które mają blip.</td></tr><tr><td>Ikona blipa</td><td><code>BlipSprite</code></td><td>ikona blipa</td><td>446</td><td>Wybierana z wizualnej listy ikon. Dla własnego blipa nadal można wpisać dowolny numer.</td></tr><tr><td>Kolor blipa</td><td><code>BlipColor</code></td><td>kolor blipa</td><td>47</td><td>Wybierany z wizualnej listy kolorów.</td></tr><tr><td>Rozmiar blipa</td><td><code>BlipScale</code></td><td>0,2 do 2</td><td>0,8</td><td>Rozmiar blipa.</td></tr></tbody></table>',23)])])}const w=d(i,[["render",n]]);export{y as __pageData,w as default};
